<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lumina · Service &amp; kitchen</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/service.css"><script src="/assets/js/service.js" defer></script></head>
<body class="service-body" data-mode="{{mode}}"><a class="skip-link" href="#service-main">Skip to workspace</a>
<header class="service-header"><a class="brand" href="/">LUMINA <span>Kitchen &amp; Terrace</span></a><nav aria-label="Staff workspaces" id="service-nav"></nav><div><span id="service-user"></span> <button type="button" id="service-logout" class="button ghost">Sign out</button></div></header>
<main id="service-main"><div class="service-title"><div><p class="eyebrow">Live dinner service</p><h1 id="service-heading">Loading workspace…</h1></div><form id="service-filters"><label>Service date<input type="date" name="date" required></label><label id="station-field" hidden>Station<select name="station" aria-label="Station"><option value="all">All stations</option><option>cold</option><option>grill</option><option>fry</option><option>hot</option><option>pastry</option><option>bar</option></select></label><button class="button ghost" type="submit">Refresh</button></form></div>
<p id="service-feedback" role="status" hidden></p><p class="muted">All outstanding service stays visible. The service date filters completed rounds and recent served tickets.</p><p id="service-sync" class="muted">Connecting…</p><div id="service-content"></div></main>
<dialog id="service-dialog"><header><h2 id="service-dialog-title"></h2><button type="button" id="service-dialog-close" class="button ghost">Close</button></header><p id="service-dialog-feedback" role="status" hidden></p><div id="service-dialog-content"></div></dialog></body></html>
